        b"[1]",
        b"{}",
        br#"{"Command": 5}"#,
        br#"{"Command": "Nope"}"#,
        b"{\"Command\": \"Tick\", \"Seconds\": 1} trailing",
    ];
    for line in lines {
        assert_eq!(error_code(&session.raw(line)), "InvalidRequest", "{line:?}");
    }
    assert_eq!(error_code(&session.raw(b"{\"Command\": \"ListQueues\xff\"}")), "InvalidRequest");
    assert_eq!(session.run(json!({"Command": "Tick", "Seconds": 7})), json!({"ok": true, "Now": 7}));
}

