        let line = format!(r#"{{"Command": "Tick", "Seconds": {seconds}}}"#);
        assert_eq!(error_code(&session.raw(line.as_bytes())), "InvalidParameterValue", "{seconds}");
    }
    let reply = session.raw(br#"{"Command": "Tick", "Seconds": 30}"#);
