#[test]
fn delayed_messages_become_visible_after_their_delay() {
    let mut session = Session::new();
    session.create("q", json!({"DelaySeconds": 10}));
    session.send("q", "queue-delay");
    session.run(json!({"Command": "SendMessage", "QueueName": "q", "Body": "own-delay", "DelaySeconds": 2}));
    assert_eq!(session.counts("q"), json!({"Visible": 0, "InFlight": 0, "Delayed": 2}));
