}

#[test]
fn send_message_validates_parameters_and_queue_type() {
    let mut session = Session::new();
    session.create("q", json!({}));
    session.create("f.fifo", json!({"Fifo": true}));
    let big = "x".repeat(1025);
    let table = [
        (json!({"QueueName": "q", "Body": big}), "InvalidParameterValue"),
        (json!({"QueueName": "q", "Body": "a", "DelaySeconds": 901}), "InvalidParameterValue"),
        (json!({"QueueName": "q", "Body": "a", "GroupId": "bad id"}), "InvalidParameterValue"),
        (json!({"QueueName": "q", "Body": "a", "GroupId": "g"}), "UnsupportedOperation"),
        (json!({"QueueName": "q", "Body": "a", "DeduplicationId": "d"}), "UnsupportedOperation"),
        (json!({"QueueName": "f.fifo", "Body": "a", "GroupId": "g", "DeduplicationId": "d", "DelaySeconds": 0}), "UnsupportedOperation"),
        (json!({"QueueName": "f.fifo", "Body": "a", "DeduplicationId": "d"}), "MissingParameter"),
